import os,re,collections
root='AlgebraicJacobian'
files={}
for dp,dn,fn in os.walk(root):
    for f in fn:
        if f.endswith('.lean'):
            p=os.path.join(dp,f)
            mod=p[:-5].replace('/','.')
            files[mod]=p
imports={}
sorries={}
for mod,p in files.items():
    txt=open(p,encoding='utf8').read()
    imports[mod]=re.findall(r'^import\s+(AlgebraicJacobian[\w.]*)',txt,re.M)
    # crude: count 'sorry' token outside of comments is hard; just token search
    sorries[mod]=len(re.findall(r'\bsorry\b',txt))

def cone(m):
    seen=set(); st=[m]
    while st:
        x=st.pop()
        if x in seen: continue
        seen.add(x)
        for y in imports.get(x,[]):
            if y not in seen: st.append(y)
    return seen

targets=['AlgebraicJacobian.RiemannRoch.CoverageDrop',
 'AlgebraicJacobian.Curve.SepPointsDense',
 'AlgebraicJacobian.Curve.SeparablyClosedPoints',
 'AlgebraicJacobian.Picard.DivisorFamilyFieldSurj',
 'AlgebraicJacobian.Picard.Pic0ChartLocusOpen',
 'AlgebraicJacobian.Picard.Pic0ChartLocusClass',
 'AlgebraicJacobian.Picard.Pic0ChartLocusFibreField']
for t in targets:
    c=cone(t)
    bad=[(m,sorries[m]) for m in c if sorries.get(m,0)>0]
    print(t, 'cone size',len(c), 'SORRY MODULES:', bad)
EOF

